sources.NoticeSink.ets:
export class NoticeSink {
  report(command: string): void {
    console.info('cached content remains usable after updating')
  }
  emit(): void {
    console.info('network task finished with cached result')
  }
}

sources.NoticeRelay.ets:
export class NoticeRelay {
  private logger: NoticeSink
  notify(command: string): void {
    this.logger.report(command)
  }
}

sources.CommitButton.ets:
export class CommitButton {
  dispatchCommit(value: string): void {
    this.service.submit(value)
  }
}

